کد زیر را یک‌جا در Console اجرا کن و بعد دست به موس و کیبورد نزن:

JavaScript
(async () => {
  const sleep = ms => new Promise(resolve => setTimeout(resolve, ms));

  // پیدا کردن اسکرولر واقعی
  const scroller = [...document.querySelectorAll('div')].find(el =>
    el.scrollHeight > el.clientHeight + 100 &&
    getComputedStyle(el).overflowY === 'auto' &&
    el.clientHeight < 1000
  );

  if (!scroller) {
    console.log('❌ اسکرولر واقعی پیدا نشد.');
    return;
  }

  const STEP = 2000;
  const WAIT = 700;

  const snapshots = [];
  const seen = new Map();

  function getMessages() {
    return [...document.querySelectorAll('[data-message-author-role]')];
  }

  function fingerprint(el) {
    const role = el.getAttribute('data-message-author-role') || '';
    const text = (el.innerText || '').trim();

    return role + '|' + text;
  }

  function capture(step, direction) {
    const messages = getMessages();

    const current = [];

    messages.forEach((el, index) => {
      const role = el.getAttribute('data-message-author-role') || '';
      const text = (el.innerText || '').trim();

      const fp = fingerprint(el);

      if (!seen.has(fp)) {
        seen.set(fp, {
          role,
          text,
          firstSeenAt: step
        });
      }

      current.push({
        index,
        role,
        textStart: text.slice(0, 120),
        textLength: text.length
      });
    });

    snapshots.push({
      step,
      direction,
      scrollTop: Math.round(scroller.scrollTop),
      scrollHeight: Math.round(scroller.scrollHeight),
      clientHeight: Math.round(scroller.clientHeight),
      domMessages: messages.length,
      current
    });
  }

  console.clear();

  console.log('========== AUTO SCROLL TEST ==========');
  console.log('Starting...');
  console.log('Scroll height:', scroller.scrollHeight);

  // اول برو انتهای گفتگو
  scroller.scrollTop = scroller.scrollHeight;
  await sleep(1200);

  capture(0, 'start-bottom');

  let step = 1;

  while (scroller.scrollTop > 0) {
    const before = scroller.scrollTop;

    scroller.scrollTop = Math.max(
      0,
      scroller.scrollTop - STEP
    );

    await sleep(WAIT);

    capture(step, 'up');

    const after = scroller.scrollTop;

    if (after === before) {
      break;
    }

    step++;
  }

  console.log('========== TEST FINISHED ==========');

  console.log('Snapshots:', snapshots.length);
  console.log('Unique message fingerprints:', seen.size);

  console.log(
    'Final scrollTop:',
    Math.round(scroller.scrollTop)
  );

  console.log(
    'Final scrollHeight:',
    Math.round(scroller.scrollHeight)
  );

  console.log('========== SNAPSHOTS ==========');
  console.log(snapshots);

  console.log('========== UNIQUE MESSAGES ==========');
  console.log([...seen.values()]);

  console.log('========== END ==========');
})();
