JavaScript
(async () => {
  const sleep = ms => new Promise(r => setTimeout(r, ms));

  const scroller = [...document.querySelectorAll('div')].find(el =>
    el.scrollHeight > el.clientHeight + 100 &&
    getComputedStyle(el).overflowY === 'auto' &&
    el.clientHeight < 1000
  );

  if (!scroller) {
    console.log('❌ اسکرولر پیدا نشد');
    return;
  }

  const MIN_STEP = 400;
  const MAX_STEP = 3000;

  let step = 1200;
  let previous = null;
  let iteration = 0;

  function getState() {
    const messages = [
      ...document.querySelectorAll('[data-message-author-role]')
    ];

    const items = messages.map(el => ({
      role: el.getAttribute('data-message-author-role') || '',
      text: (el.innerText || '').trim()
    }));

    return {
      scrollTop: Math.round(scroller.scrollTop),
      scrollHeight: Math.round(scroller.scrollHeight),
      count: items.length,
      first: items[0]
        ? items[0].role + '|' + items[0].text
        : '',
      last: items.at(-1)
        ? items.at(-1).role + '|' + items.at(-1).text
        : '',
      fingerprints: items.map(
        x => x.role + '|' + x.text
      )
    };
  }

  function overlap(a, b) {
    if (!a || !b) return 0;

    const setA = new Set(a.fingerprints);
    const setB = new Set(b.fingerprints);

    let common = 0;

    for (const x of setA) {
      if (setB.has(x)) common++;
    }

    return common;
  }

  console.clear();

  console.log('========== ADAPTIVE SCROLL TEST ==========');

  // شروع از انتهای گفتگو
  scroller.scrollTop = scroller.scrollHeight;
  await sleep(1000);

  previous = getState();

  while (scroller.scrollTop > 0 && iteration < 300) {
    iteration++;

    const before = scroller.scrollTop;

    scroller.scrollTop = Math.max(
      0,
      scroller.scrollTop - step
    );

    await sleep(700);

    const current = getState();

    const common = overlap(previous, current);

    const maxCount = Math.max(
      previous.count,
      current.count
    );

    const overlapRatio =
      maxCount > 0
        ? common / maxCount
        : 0;

    const firstChanged =
      previous.first !== current.first;

    const lastChanged =
      previous.last !== current.last;

    const countChanged =
      previous.count !== current.count;

    console.log({
      iteration,
      before,
      after: current.scrollTop,
      step,
      count: current.count,
      countChanged,
      firstChanged,
      lastChanged,
      overlap: common,
      overlapRatio: Number(overlapRatio.toFixed(2))
    });

    /*
      کنترل ساده:

      overlap خیلی زیاد
      → پنجره‌ها بیش از حد روی هم افتاده‌اند
      → کمی سریع‌تر

      overlap خیلی کم
      → خطر جاافتادن پیام
      → آهسته‌تر

      بدون تغییر قابل توجه
      → کمی بیشتر حرکت کن
    */

    if (overlapRatio > 0.75) {
      step = Math.min(
        MAX_STEP,
        Math.round(step * 1.25)
      );
    } else if (overlapRatio < 0.35) {
      step = Math.max(
        MIN_STEP,
        Math.round(step * 0.65)
      );
    }

    previous = current;

    if (current.scrollTop === 0) {
      break;
    }
  }

  console.log('========== FINISHED ==========');
  console.log('Iterations:', iteration);
  console.log('Final scrollTop:', scroller.scrollTop);
  console.log('Final step:', step);
  console.log('================================');
})();
