👍 پس فعلاً فقط یک متغیر جدید اضافه می‌کنیم و منطق step را دست نمی‌زنیم. اینطوری دقیقاً می‌فهمیم «وسط» چه اطلاعات تازه‌ای می‌دهد.

این نسخه را اجرا کن؛ مثل قبل، بعد از اجرا کل خروجی را یکجا بفرست. 👀

JavaScript
(async () => {
  const sleep = ms => new Promise(r => setTimeout(r, ms));

  const scroller = [...document.querySelectorAll('div')].find(el =>
    el.scrollHeight > el.clientHeight + 100 &&
    getComputedStyle(el).overflowY === 'auto' &&
    el.clientHeight < 1000
  );

  if (!scroller) {
    console.log('❌ اسکرولر پیدا نشد');
    return;
  }

  const MIN_STEP = 400;
  const MAX_STEP = 3000;

  let step = 1200;
  let previous = null;
  let iteration = 0;

  function getState() {
    const messages = [
      ...document.querySelectorAll('[data-message-author-role]')
    ];

    const items = messages.map(el => ({
      role: el.getAttribute('data-message-author-role') || '',
      text: (el.innerText || '').trim()
    }));

    const middleIndex =
      items.length > 0
        ? Math.floor((items.length - 1) / 2)
        : -1;

    return {
      scrollTop: Math.round(scroller.scrollTop),
      scrollHeight: Math.round(scroller.scrollHeight),
      count: items.length,

      first: items[0]
        ? items[0].role + '|' + items[0].text
        : '',

      middle: middleIndex >= 0
        ? items[middleIndex].role + '|' + items[middleIndex].text
        : '',

      last: items.at(-1)
        ? items.at(-1).role + '|' + items.at(-1).text
        : '',

      fingerprints: items.map(
        x => x.role + '|' + x.text
      )
    };
  }

  function overlap(a, b) {
    if (!a || !b) return 0;

    const setA = new Set(a.fingerprints);
    const setB = new Set(b.fingerprints);

    let common = 0;

    for (const x of setA) {
      if (setB.has(x)) common++;
    }

    return common;
  }

  console.clear();

  console.log('========== THREE-POINT SCROLL TEST ==========');

  scroller.scrollTop = scroller.scrollHeight;
  await sleep(1000);

  previous = getState();

  while (scroller.scrollTop > 0 && iteration < 300) {
    iteration++;

    const before = scroller.scrollTop;

    scroller.scrollTop = Math.max(
      0,
      scroller.scrollTop - step
    );

    await sleep(700);

    const current = getState();

    const common = overlap(previous, current);

    const maxCount = Math.max(
      previous.count,
      current.count
    );

    const overlapRatio =
      maxCount > 0
        ? common / maxCount
        : 0;

    const firstChanged =
      previous.first !== current.first;

    const middleChanged =
      previous.middle !== current.middle;

    const lastChanged =
      previous.last !== current.last;

    const countChanged =
      previous.count !== current.count;

    console.log({
      iteration,
      before,
      after: current.scrollTop,
      step,

      count: current.count,
      countChanged,

      firstChanged,
      middleChanged,
      lastChanged,

      overlap: common,
      overlapRatio: Number(overlapRatio.toFixed(2))
    });

    // همان کنترل قبلی؛ فعلاً هیچ تغییری در منطق نمی‌دهیم

    if (overlapRatio > 0.75) {
      step = Math.min(
        MAX_STEP,
        Math.round(step * 1.25)
      );
    } else if (overlapRatio < 0.35) {
      step = Math.max(
        MIN_STEP,
        Math.round(step * 0.65)
      );
    }

    previous = current;

    if (current.scrollTop === 0) {
      break;
    }
  }

  console.log('========== FINISHED ==========');
  console.log('Iterations:', iteration);
  console.log('Final scrollTop:', scroller.scrollTop);
  console.log('Final step:', step);
  console.log('================================');
})();

این بار هیچ چیز دیگری را تغییر ندادیم؛ بنابراین اگر رفتار middleChanged الگوی جالبی نشان بدهد، می‌توانیم با اطمینان بیشتری بگوییم اطلاعات «وسط» واقعاً به تشخیص حرکت پنجره کمک می‌کند یا نه.

آها، این خطا از منطق کد نیست؛ حتی به خطی که اضافه کردیم (middle) هم نرسیده. 👀

