(async () => {
  const MIN_STEP = 400;
  const MAX_STEP = 3000;
  let step = 1200;

  function getScroller() {
    return [...document.querySelectorAll('*')].find(el => {
      const s = getComputedStyle(el);
      return (
        s.overflowY === 'auto' &&
        el.scrollHeight > el.clientHeight + 500
      );
    });
  }

  function getMessages() {
    return [...document.querySelectorAll('[data-message-author-role]')]
      .map(el => ({
        role: el.getAttribute('data-message-author-role'),
        text: el.innerText.trim()
      }));
  }

  function fingerprint(msg) {
    if (!msg) return null;
    return msg.role + '|' + msg.text;
  }

  const scroller = getScroller();

  if (!scroller) {
    console.log('❌ اسکرولر پیدا نشد');
    return;
  }

  console.log('🚀 شروع تست middleShift');
  console.log('scrollHeight:', scroller.scrollHeight);

  scroller.scrollTop = scroller.scrollHeight;
  await new Promise(r => setTimeout(r, 1000));

  let previous = getMessages();

  if (!previous.length) {
    console.log('❌ هیچ پیامی پیدا نشد');
    return;
  }

  let iteration = 0;

  while (true) {
    iteration++;

    // پیام میانیِ پنجره فعلی
    const middleIndexBefore = Math.floor((previous.length - 1) / 2);
    const previousMiddle = previous[middleIndexBefore];
    const previousMiddleFP = fingerprint(previousMiddle);

    const beforeScroll = scroller.scrollTop;

    // فعلاً step را تغییر نمی‌دهیم بر اساس middleShift
    scroller.scrollTop = Math.max(0, beforeScroll - step);

    await new Promise(r => setTimeout(r, 700));

    const current = getMessages();

    const currentFPs = current.map(fingerprint);

    const middleIndexAfter =
      currentFPs.indexOf(previousMiddleFP);

    const middleFound = middleIndexAfter !== -1;

    const middleShift = middleFound
      ? middleIndexAfter - middleIndexBefore
      : null;

    console.log({
      iteration,
      before: Math.round(beforeScroll),
      after: Math.round(scroller.scrollTop),
      step,
      countBefore: previous.length,
      countAfter: current.length,
      middleIndexBefore,
      middleIndexAfter,
      middleFound,
      middleShift
    });

    // فقط برای اینکه مسیر آزمایش مثل قبل تمام شود:
    // step فعلاً از middleShift استفاده نمی‌کند.
    if (scroller.scrollTop <= 0) {
      console.log('🏁 به ابتدای گفتگو رسیدیم');
      break;
    }

    previous = current;
  }

  console.log('✅ تست تمام شد');
})();
