بزن بریم 😎

این نسخه فقط همان تغییر ضروری را به کد قبلی اضافه می‌کند:
وقتی middle گم شد، تعداد گام‌های برگشتی را می‌شماریم؛ وقتی پیدا شد، به‌اندازهٔ N + 2 حرکت رو به جلو انجام می‌دهیم و بعد دوباره وارد حرکت عادی می‌شویم.

JavaScript
(async () => {
  const STEP_SIZE = 1200;
  const WAIT = 700;

  let step = STEP_SIZE;
  let recovery = false;
  let recoverySteps = 0;
  let forwardRemaining = 0;

  function getScroller() {
    return [...document.querySelectorAll('*')].find(el => {
      const s = getComputedStyle(el);
      return (
        s.overflowY === 'auto' &&
        el.scrollHeight > el.clientHeight + 500
      );
    });
  }

  function getMessages() {
    return [...document.querySelectorAll('[data-message-author-role]')]
      .map(el => ({
        role: el.getAttribute('data-message-author-role'),
        text: el.innerText.trim()
      }));
  }

  function fingerprint(msg) {
    if (!msg) return null;
    return msg.role + '|' + msg.text;
  }

  const scroller = getScroller();

  if (!scroller) {
    console.log('❌ اسکرولر پیدا نشد');
    return;
  }

  scroller.scrollTop = scroller.scrollHeight;
  await new Promise(r => setTimeout(r, 1000));

  let previous = getMessages();

  if (!previous.length) {
    console.log('❌ پیام پیدا نشد');
    return;
  }

  let iteration = 0;

  while (true) {
    iteration++;

    const middleIndexBefore =
      Math.floor((previous.length - 1) / 2);

    const previousMiddle =
      previous[middleIndexBefore];

    const previousMiddleFP =
      fingerprint(previousMiddle);

    const beforeScroll =
      scroller.scrollTop;

    // اگر در مرحله‌ی جلو رفتنِ پس از ریکاوری هستیم
    // فقط حرکت می‌کنیم و شمارش را کم می‌کنیم.
    if (forwardRemaining > 0) {
      scroller.scrollTop = Math.max(
        0,
        Math.min(
          scroller.scrollHeight,
          beforeScroll - STEP_SIZE
        )
      );

      await new Promise(r => setTimeout(r, WAIT));

      forwardRemaining--;

      console.log({
        iteration,
        mode: '➡️ عبور از محل مشکل',
        before: Math.round(beforeScroll),
        after: Math.round(scroller.scrollTop),
        forwardRemaining
      });

      previous = getMessages();

      if (scroller.scrollTop <= 0) {
        console.log('🏁 به ابتدای گفتگو رسیدیم');
        break;
      }

      continue;
    }

    // حرکت اصلی یا حرکت ریکاوری
    scroller.scrollTop = Math.max(
      0,
      Math.min(
        scroller.scrollHeight,
        beforeScroll - step
      )
    );

    await new Promise(r => setTimeout(r, WAIT));

    const current = getMessages();

    const currentFPs =
      current.map(fingerprint);

    const middleIndexAfter =
      currentFPs.indexOf(previousMiddleFP);

    const middleFound =
      middleIndexAfter !== -1;

    console.log({
      iteration,
      mode: recovery ? '↩️ ریکاوری' : '➡️ اصلی',
      before: Math.round(beforeScroll),
      after: Math.round(scroller.scrollTop),
      step,
      countBefore: previous.length,
      countAfter: current.length,
      middleIndexBefore,
      middleIndexAfter,
      middleFound,
      recoverySteps
    });

    // middle گم شد → شروع ریکاوری
    if (!middleFound && !recovery) {
      recovery = true;
      step = -STEP_SIZE;
      recoverySteps = 1;

      console.log(
        '⚠️ middle پیدا نشد → شروع عقب‌گرد'
      );
    }

    // هنوز در ریکاوری هستیم و middle پیدا نشد
    else if (!middleFound && recovery) {
      recoverySteps++;

      console.log(
        `↩️ middle هنوز پیدا نشده → گام برگشت ${recoverySteps}`
      );
    }

    // middle در ریکاوری پیدا شد
    else if (middleFound && recovery) {
      const forwardMoves =
        recoverySteps + 2;

      console.log({
        message: '✅ middle پیدا شد → عبور از محل مشکل',
        recoverySteps,
        forwardMoves
      });

      recovery = false;
      step = STEP_SIZE;

      forwardRemaining = forwardMoves;

      recoverySteps = 0;
    }

    previous = current;

    if (scroller.scrollTop <= 0) {
      console.log('🏁 به ابتدای گفتگو رسیدیم');
      break;
    }

    if (
      scroller.scrollTop >=
      scroller.scrollHeight - scroller.clientHeight
    ) {
      console.log('🏁 به انتهای گفتگو رسیدیم');
      break;
    }
  }

  console.log('✅ تست تمام شد');
})();

فقط یک نکتهٔ مهم در این تست: در لاگ دنبال این بخش باش:

middle پیدا شد → عبور از محل مشکل
recoverySteps: N
forwardMoves: N + 2

و بعد ببین آیا واقعاً یک گام جلوتر از محل وقوع مشکل قرار می‌گیریم یا نه.

اگر دوباره رفتار عجیب یا حلقه دیدیم، فعلاً هیچ معماری جدیدی اضافه نمی‌کنیم؛ فقط همان رفتار را از روی لاگ بررسی می‌کنیم. 🏹

