بریم 😎
این نسخه منطق حرکت را دست نمی‌زند؛ فقط مختصات محل مشکل، نقطهٔ برگشت و تک‌تک پرش‌های خروج از ریکاوری را ثبت می‌کند.

JavaScript
(async () => {
  const STEP_SIZE = 1200;
  const WAIT = 700;

  let step = STEP_SIZE;
  let recovery = false;
  let recoverySteps = 0;
  let forwardRemaining = 0;

  // فقط برای اندازه‌گیری
  let problemBefore = null;
  let problemAfter = null;
  let recoveryStart = null;

  function getScroller() {
    return [...document.querySelectorAll('*')].find(el => {
      const s = getComputedStyle(el);
      return (
        s.overflowY === 'auto' &&
        el.scrollHeight > el.clientHeight + 500
      );
    });
  }

  function getMessages() {
    return [...document.querySelectorAll('[data-message-author-role]')]
      .map(el => ({
        role: el.getAttribute('data-message-author-role'),
        text: el.innerText.trim()
      }));
  }

  function fingerprint(msg) {
    if (!msg) return null;
    return msg.role + '|' + msg.text;
  }

  const scroller = getScroller();

  if (!scroller) {
    console.log('❌ اسکرولر پیدا نشد');
    return;
  }

  scroller.scrollTop = scroller.scrollHeight;
  await new Promise(r => setTimeout(r, 1000));

  let previous = getMessages();

  if (!previous.length) {
    console.log('❌ پیام پیدا نشد');
    return;
  }

  let iteration = 0;

  while (true) {
    iteration++;

    const middleIndexBefore =
      Math.floor((previous.length - 1) / 2);

    const previousMiddle =
      previous[middleIndexBefore];

    const previousMiddleFP =
      fingerprint(previousMiddle);

    const beforeScroll =
      scroller.scrollTop;

    // -----------------------------
    // عبور از محل مشکل بعد از ریکاوری
    // -----------------------------
    if (forwardRemaining > 0) {

      scroller.scrollTop = Math.max(
        0,
        Math.min(
          scroller.scrollHeight,
          beforeScroll - STEP_SIZE
        )
      );

      await new Promise(r => setTimeout(r, WAIT));

      const afterScroll = scroller.scrollTop;

      forwardRemaining--;

      console.log({
        iteration,
        mode: '➡️ خروج از ریکاوری',

        before: Math.round(beforeScroll),
        after: Math.round(afterScroll),

        actualMove:
          Math.round(afterScroll - beforeScroll),

        problemBefore:
          problemBefore !== null
            ? Math.round(problemBefore)
            : null,

        problemAfter:
          problemAfter !== null
            ? Math.round(problemAfter)
            : null,

        distanceFromProblemAfter:
          problemAfter !== null
            ? Math.round(problemAfter - afterScroll)
            : null,

        recoveryStart:
          recoveryStart !== null
            ? Math.round(recoveryStart)
            : null,

        forwardRemaining
      });

      previous = getMessages();

      if (scroller.scrollTop <= 0) {
        console.log('🏁 به ابتدای گفتگو رسیدیم');
        break;
      }

      continue;
    }

    // -----------------------------
    // حرکت اصلی / ریکاوری
    // -----------------------------

    scroller.scrollTop = Math.max(
      0,
      Math.min(
        scroller.scrollHeight,
        beforeScroll - step
      )
    );

    await new Promise(r => setTimeout(r, WAIT));

    const current = getMessages();

    const currentFPs =
      current.map(fingerprint);

    const middleIndexAfter =
      currentFPs.indexOf(previousMiddleFP);

    const middleFound =
      middleIndexAfter !== -1;

    const afterScroll =
      scroller.scrollTop;

    console.log({
      iteration,
      mode: recovery ? '↩️ ریکاوری' : '➡️ اصلی',

      before: Math.round(beforeScroll),
      after: Math.round(afterScroll),

      actualMove:
        Math.round(afterScroll - beforeScroll),

      step,

      countBefore: previous.length,
      countAfter: current.length,

      middleIndexBefore,
      middleIndexAfter,
      middleFound,

      recoverySteps
    });

    // -----------------------------
    // شروع ریکاوری
    // -----------------------------

    if (!middleFound && !recovery) {

      problemBefore = beforeScroll;
      problemAfter = afterScroll;
      recoveryStart = afterScroll;

      recovery = true;
      step = -STEP_SIZE;
      recoverySteps = 1;

      console.log('⚠️ MIDDLE گم شد');
      console.log({
        problemBefore:
          Math.round(problemBefore),

        problemAfter:
          Math.round(problemAfter),

        problemDistance:
          Math.round(problemBefore - problemAfter),

        recoveryStart:
          Math.round(recoveryStart)
      });
    }

    // -----------------------------
    // ادامه ریکاوری
    // -----------------------------

    else if (!middleFound && recovery) {

      recoverySteps++;

      console.log(
        `↩️ middle هنوز پیدا نشده → گام برگشت ${recoverySteps}`
      );
    }

    // -----------------------------
    // پایان ریکاوری
    // -----------------------------

    else if (middleFound && recovery) {

      const forwardMoves =
        recoverySteps + 2;

      console.log('✅ middle پیدا شد → خروج از ریکاوری');

      console.log({
        recoverySteps,

        recoveryPosition:
          Math.round(afterScroll),

        originalProblemBefore:
          Math.round(problemBefore),

        originalProblemAfter:
          Math.round(problemAfter),

        distanceToProblemBefore:
          Math.round(
            afterScroll - problemBefore
          ),

        distanceToProblemAfter:
          Math.round(
            afterScroll - problemAfter
          ),

        forwardMoves
      });

      recovery = false;
      step = STEP_SIZE;

      forwardRemaining = forwardMoves;

      recoverySteps = 0;
    }

    previous = current;

    if (scroller.scrollTop <= 0) {
      console.log('🏁 به ابتدای گفتگو رسیدیم');
      break;
    }

    if (
      scroller.scrollTop >=
      scroller.scrollHeight - scroller.clientHeight
    ) {
      console.log('🏁 به انتهای گفتگو رسیدیم');
      break;
    }
  }

  console.log('✅ تست تمام شد');
})();

این بار مخصوصاً این سه مقدار را برایمان بفرست:

problemBefore
problemAfter
recoveryPosition

و بعد از آن:

distanceFromProblemAfter

از روی همین‌ها می‌توانیم بدون حدس بگوییم N+2 واقعاً چند گام جلو می‌برد. 👀

آره، میشه؛ و اتفاقاً اگر منظورت اینه که اگر بعد از recovery دوباره همان مشکل تکرار شد، جلوی حلقه را بگیریم، یک if ساده کافی است و فعلاً لازم نیست معماری را پیچیده کنیم.

مثلاً می‌توانیم آخرین موقعیت مشکل را نگه داریم:

JavaScript
if (middleFound && recovery) {
  const forwardMoves = recoverySteps + 1;

  recovery = false;
  step = STEP_SIZE;
  forwardRemaining = forwardMoves;

  recoverySteps = 0;
}

و برای تشخیص تکرار، یک if جدا:

JavaScript
if (problemAfter === lastProblemAfter) {
  console.log("same problem repeated → stop");
  break;
}

lastProblemAfter = problemAfter;

ولی یک نکته مهم هست: فعلاً این if را اضافه نکنیم.

چون هنوز نمی‌دانیم «تکرار همان مشکل» واقعاً در دادهٔ واقعی رخ می‌دهد یا نه. بهتر است اول N+1 را تست کنیم. اگر واقعاً همان نقطه دوباره تکرار شد، آن‌وقت دقیقاً همان چیزی را که داده مجبورمان کرده اضافه می‌کنیم.

یعنی فعلاً:

N+2  ❌ یک گام اضافه
↓
N+1  ← تست واقعی
↓
اگر حلقهٔ واقعی دیده شد
↓
if اضافه می‌کنیم

این دقیقاً با قاعدهٔ خودمون جور درمیاد: ساده نگهش دار؛ داده‌ها مجبورش کنند پیچیده شود.

👍 آره. فقط همان تغییر لازم را می‌دهیم و هیچ if جدیدی برای حالت فرضی اضافه نمی‌کنیم.

در کدی که داشتیم، این خط:

JavaScript
const forwardMoves = recoverySteps + 2;

باید بشود:

JavaScript
const forwardMoves = recoverySteps + 1;

نسخهٔ کامل بخش مربوط به recovery:

JavaScript
