}

if (!middleFound && !recovery) {
  recovery = true;
  step = -STEP_SIZE;
  recoverySteps = 1;

  console.log("→ recovery");

} else if (!middleFound && recovery) {
  recoverySteps++;

} else if (middleFound && recovery) {

  // یک گام جلوتر از محل مشکل
  const forwardMoves = recoverySteps + 1;

  console.log({
    recoverySteps,
    forwardMoves
  });

  recovery = false;
  step = STEP_SIZE;
  forwardRemaining = forwardMoves;
  recoverySteps = 0;

  console.log("→ main");
}

