حتماً. این نسخه همان کد قبلی است با فقط اصلاح N+2 → N+1 و همان لاگ‌های اندازه‌گیری که برای تریس لازم داریم. هیچ منطق جدیدی برای جلوگیری از loop اضافه نکردم.

JavaScript
(async () => {
  const STEP_SIZE = 1200;
  const WAIT = 700;

  const wait = ms => new Promise(resolve => setTimeout(resolve, ms));

  // پیدا کردن اسکرولر واقعی
  const scroller = [...document.querySelectorAll("div")].find(el => {
    const s = getComputedStyle(el);
    return (
      s.overflowY === "auto" &&
      el.scrollHeight > el.clientHeight + 1000
    );
  });

  if (!scroller) {
    console.log("Scroller not found");
    return;
  }

  console.log("Scroller found:", scroller);

  function getMessages() {
    return [...document.querySelectorAll("[data-message-author-role]")]
      .map(el => ({
        role: el.getAttribute("data-message-author-role"),
        text: el.innerText.trim()
      }))
      .filter(x => x.text);
  }

  function fingerprint(message) {
    if (!message) return null;
    return message.role + "::" + message.text;
  }

  let step = STEP_SIZE;

  let recovery = false;
  let recoverySteps = 0;
  let forwardRemaining = 0;

  let previousMessages = getMessages();

  let iteration = 0;

  while (true) {
    iteration++;

    const beforeScroll = scroller.scrollTop;

    const beforeMessages = getMessages();

    if (beforeMessages.length === 0) {
      console.log("No messages found");
      break;
    }

    // middle پیام فعلی
    const middleIndexBefore = Math.floor(
      beforeMessages.length / 2
    );

    const previousMiddle =
      beforeMessages[middleIndexBefore];

    const previousMiddleFingerprint =
      fingerprint(previousMiddle);

    // حرکت
    const target = Math.max(
      0,
      Math.min(
        scroller.scrollHeight,
        beforeScroll - step
      )
    );

    scroller.scrollTop = target;

    await wait(WAIT);

    const afterScroll = scroller.scrollTop;

    const afterMessages = getMessages();

    // پیدا کردن همان middle قبلی در DOM جدید
    const middleIndexAfter =
      afterMessages.findIndex(
        m => fingerprint(m) === previousMiddleFingerprint
      );

    const middleFound = middleIndexAfter !== -1;

    const actualMove =
      beforeScroll - afterScroll;

    console.log({
      iteration,
      mode:
        forwardRemaining > 0
          ? "forward_after_recovery"
          : recovery
          ? "recovery"
          : "main",

      beforeScroll,
      afterScroll,
      actualMove,

      step,

      countBefore: beforeMessages.length,
      countAfter: afterMessages.length,

      middleIndexBefore,
      middleIndexAfter,
      middleFound
    });

    /*
     * اگر در حال انجام حرکت‌های بعد از recovery هستیم،
     * هر حرکت را جداگانه انجام می‌دهیم.
     */
    if (forwardRemaining > 0) {
      forwardRemaining--;

      console.log({
        recoveryForwardStep: true,
        forwardRemaining
      });

      continue;
    }

    /*
     * مشکل تازه پیدا شده:
     * middle در حرکت اصلی گم شده.
     */
    if (!middleFound && !recovery) {

      recovery = true;

      step = -STEP_SIZE;

      recoverySteps = 1;

      console.log("→ recovery");

      continue;
    }

    /*
     * هنوز در recovery هستیم و middle پیدا نشده.
     * یک قدم دیگر به عقب می‌رویم.
     */
    if (!middleFound && recovery) {

      recoverySteps++;

      console.log({
        recoveryStillActive: true,
        recoverySteps
      });

      continue;
    }

    /*
     * middle دوباره پیدا شده.
     *
     * recoverySteps = تعداد قدم‌هایی که
     * برای پیدا کردن middle به عقب رفتیم.
     *
     * بعد از برگشتن به محل مشکل،
     * فقط یک قدم جلوتر از محل مشکل می‌رویم.
     *
     * بنابراین:
     *
     * forwardMoves = recoverySteps + 1
     */
    if (middleFound && recovery) {

      const forwardMoves =
        recoverySteps + 1;

      console.log({
        recoveryFinished: true,
        recoverySteps,
        forwardMoves,
        positionAfterRecovery: afterScroll
      });

      recovery = false;

      step = STEP_SIZE;

      forwardRemaining = forwardMoves;

      recoverySteps = 0;

      console.log("→ main");

      continue;
    }

    /*
     * پایان طبیعی در ابتدای صفحه
     */
    if (afterScroll <= 0) {
      console.log("Reached top.");
      break;
    }
  }

  console.log("Finished.");
})();

