حاضرم 😎
این بار حرکت و recovery را دست نمی‌زنیم؛ فقط یک لایهٔ اندازه‌گیری به آن اضافه می‌کنیم تا ببینیم واقعاً بین پنجرهٔ قبلی و جدید چه مقدار overlap داریم.

ایدهٔ تست:

پنجرهٔ قبل
████████████

        پنجرهٔ بعد
    ████████████

        ↓
پیام‌های مشترک = overlap

برای هر حرکت، مجموعهٔ پیام‌های قبل و بعد را با role + text مقایسه می‌کنیم و این‌ها را ثبت می‌کنیم:

countBefore

countAfter

overlapCount

overlapRatioBefore = overlap / تعداد پیام‌های پنجرهٔ قبل

overlapRatioAfter = overlap / تعداد پیام‌های پنجرهٔ بعد

overlapRatioMin = نسبت محافظه‌کارانه‌تر بر اساس پنجرهٔ کوچک‌تر

middleFound

و هیچ تصمیمی بر اساس overlap نمی‌گیریم؛ فعلاً فقط اندازه‌گیری می‌کنیم. این مهم است، چون نمی‌خواهیم قبل از دیدن داده‌ها دوباره منطق را زودتر از موعد پیچیده کنیم.

کد تست overlap
JavaScript
(async () => {
  const STEP_SIZE = 1200;
  const WAIT = 700;

  const wait = ms => new Promise(resolve => setTimeout(resolve, ms));

  // پیدا کردن اسکرولر واقعی
  const scroller = [...document.querySelectorAll("div")].find(el => {
    const s = getComputedStyle(el);

    return (
      s.overflowY === "auto" &&
      el.scrollHeight > el.clientHeight + 1000
    );
  });

  if (!scroller) {
    console.log("Scroller not found");
    return;
  }

  console.log("Scroller found:", scroller);

  function getMessages() {
    return [...document.querySelectorAll("[data-message-author-role]")]
      .map(el => ({
        role: el.getAttribute("data-message-author-role"),
        text: el.innerText.trim()
      }))
      .filter(x => x.text);
  }

  function fingerprint(message) {
    if (!message) return null;

    return message.role + "::" + message.text;
  }

  function getFingerprintSet(messages) {
    return new Set(messages.map(fingerprint));
  }

  function calculateOverlap(beforeMessages, afterMessages) {
    const beforeSet = getFingerprintSet(beforeMessages);
    const afterSet = getFingerprintSet(afterMessages);

    let overlapCount = 0;

    for (const fp of beforeSet) {
      if (afterSet.has(fp)) {
        overlapCount++;
      }
    }

    const beforeCount = beforeSet.size;
    const afterCount = afterSet.size;

    const overlapRatioBefore =
      beforeCount > 0
        ? overlapCount / beforeCount
        : 0;

    const overlapRatioAfter =
      afterCount > 0
        ? overlapCount / afterCount
        : 0;

    const smallerWindow =
      Math.min(beforeCount, afterCount);

    const overlapRatioMin =
      smallerWindow > 0
        ? overlapCount / smallerWindow
        : 0;

    return {
      overlapCount,
      overlapRatioBefore,
      overlapRatioAfter,
      overlapRatioMin
    };
  }

  let step = STEP_SIZE;

  let recovery = false;
  let recoverySteps = 0;
  let forwardRemaining = 0;

  let iteration = 0;

  while (true) {
    iteration++;

    const beforeScroll = scroller.scrollTop;

    const beforeMessages = getMessages();

    if (beforeMessages.length === 0) {
      console.log("No messages found");
      break;
    }

    // middle پیام فعلی
    const middleIndexBefore =
      Math.floor(beforeMessages.length / 2);

    const previousMiddle =
      beforeMessages[middleIndexBefore];

    const previousMiddleFingerprint =
      fingerprint(previousMiddle);

    // حرکت
    const target = Math.max(
      0,
      Math.min(
        scroller.scrollHeight,
        beforeScroll - step
      )
    );

    scroller.scrollTop = target;

    await wait(WAIT);

    const afterScroll = scroller.scrollTop;

    const afterMessages = getMessages();

    // پیدا کردن همان middle قبلی
    const middleIndexAfter =
      afterMessages.findIndex(
        m =>
          fingerprint(m) ===
          previousMiddleFingerprint
      );

    const middleFound =
      middleIndexAfter !== -1;

    const actualMove =
      beforeScroll - afterScroll;

    // محاسبه overlap واقعی
    const overlap =
      calculateOverlap(
        beforeMessages,
        afterMessages
      );

    console.log({
      iteration,

      mode:
        forwardRemaining > 0
          ? "forward_after_recovery"
          : recovery
          ? "recovery"
          : "main",

      beforeScroll,
      afterScroll,
      actualMove,

      step,

      countBefore:
        beforeMessages.length,

      countAfter:
        afterMessages.length,

      overlapCount:
        overlap.overlapCount,

      overlapRatioBefore:
        Number(
          overlap.overlapRatioBefore.toFixed(3)
        ),

      overlapRatioAfter:
        Number(
          overlap.overlapRatioAfter.toFixed(3)
        ),

      overlapRatioMin:
        Number(
          overlap.overlapRatioMin.toFixed(3)
        ),

      middleIndexBefore,
      middleIndexAfter,
      middleFound
    });

    /*
     * حرکت‌های بعد از recovery
     */
    if (forwardRemaining > 0) {

      forwardRemaining--;

      console.log({
        recoveryForwardStep: true,
        forwardRemaining
      });

      continue;
    }

    /*
     * middle گم شده در حرکت اصلی
     */
    if (!middleFound && !recovery) {

      recovery = true;

      step = -STEP_SIZE;

      recoverySteps = 1;

      console.log("→ recovery");

      continue;
    }

    /*
     * هنوز در recovery هستیم
     */
    if (!middleFound && recovery) {

      recoverySteps++;

      console.log({
        recoveryStillActive: true,
        recoverySteps
      });

      continue;
    }

    /*
     * middle دوباره پیدا شد
     */
    if (middleFound && recovery) {

      const forwardMoves =
        recoverySteps + 1;

      console.log({
        recoveryFinished: true,
        recoverySteps,
        forwardMoves,
        positionAfterRecovery:
          afterScroll
      });

      recovery = false;

      step = STEP_SIZE;

      forwardRemaining =
        forwardMoves;

      recoverySteps = 0;

      console.log("→ main");

      continue;
    }

    /*
     * رسیدن به ابتدای صفحه
     */
    if (afterScroll <= 0) {

      console.log("Reached top.");

      break;
    }
  }

  console.log("Finished.");
})();
