دقیقاً 😎
این بار به‌جای اینکه از روی تعداد overlap نتیجه بگیریم، خودِ ترتیب پیام‌های مشترک را آزمایش می‌کنیم.

یعنی برای هر حرکت می‌پرسیم:

آیا پیام مشترک داریم؟

آیا پیام‌های مشترک در هر دو snapshot پشت‌سرهم‌اند؟

آیا ترتیبشان در هر دو یکی است؟

اگر این سه برقرار باشند، آن حرکت را از نظر پیوستگی سالم حساب می‌کنیم.

اگر نباشد، لاگ دقیق همان حرکت را نگه می‌داریم.

این نسخه فعلاً هیچ تصمیمی بر اساس این آزمون نمی‌گیرد؛ فقط اندازه‌گیری می‌کند تا اگر مشکلی هست، داده خودش نشانش بدهد.

JavaScript
const STEP_SIZE = 1200;
const WAIT = 700;

function sleep(ms) {
  return new Promise(resolve => setTimeout(resolve, ms));
}

function findScroller() {
  const all = document.querySelectorAll("div");
  let best = null;
  let bestScore = 0;

  for (const el of all) {
    const style = getComputedStyle(el);

    if (
      (style.overflowY === "auto" || style.overflowY === "scroll") &&
      el.scrollHeight > el.clientHeight + 100
    ) {
      const score = el.scrollHeight - el.clientHeight;

      if (score > bestScore) {
        bestScore = score;
        best = el;
      }
    }
  }

  return best;
}

function getMessages() {
  return [...document.querySelectorAll("[data-message-author-role]")]
    .map(el => ({
      role: el.getAttribute("data-message-author-role"),
      text: el.innerText.trim()
    }))
    .filter(m => m.text);
}

function fingerprint(message) {
  return message.role + "::" + message.text;
}

function getFingerprints(messages) {
  return messages.map(fingerprint);
}

/*
  بررسی می‌کند پیام‌های مشترک بین دو snapshot
  در هر دو snapshot به همان ترتیب و به‌صورت پیوسته
  قرار گرفته‌اند یا نه.
*/
function analyzeContinuity(beforeMessages, afterMessages) {
  const before = getFingerprints(beforeMessages);
  const after = getFingerprints(afterMessages);

  const afterSet = new Set(after);

  const sharedBeforeIndexes = [];

  for (let i = 0; i < before.length; i++) {
    if (afterSet.has(before[i])) {
      sharedBeforeIndexes.push(i);
    }
  }

  const beforeSet = new Set(before);

  const sharedAfterIndexes = [];

  for (let i = 0; i < after.length; i++) {
    if (beforeSet.has(after[i])) {
      sharedAfterIndexes.push(i);
    }
  }

  /*
    آیا پیام‌های مشترک در before پشت‌سرهم‌اند؟
  */
  let contiguousBefore = true;

  for (let i = 1; i < sharedBeforeIndexes.length; i++) {
    if (sharedBeforeIndexes[i] !== sharedBeforeIndexes[i - 1] + 1) {
      contiguousBefore = false;
      break;
    }
  }

  /*
    آیا پیام‌های مشترک در after پشت‌سرهم‌اند؟
  */
  let contiguousAfter = true;

  for (let i = 1; i < sharedAfterIndexes.length; i++) {
    if (sharedAfterIndexes[i] !== sharedAfterIndexes[i - 1] + 1) {
      contiguousAfter = false;
      break;
    }
  }

  /*
    آیا ترتیب پیام‌های مشترک در دو snapshot یکسان است؟
  */
  const sharedBefore = sharedBeforeIndexes.map(i => before[i]);
  const sharedAfter = sharedAfterIndexes.map(i => after[i]);

  let sameOrder =
    sharedBefore.length === sharedAfter.length;

  if (sameOrder) {
    for (let i = 0; i < sharedBefore.length; i++) {
      if (sharedBefore[i] !== sharedAfter[i]) {
        sameOrder = false;
        break;
      }
    }
  }

  /*
    برای فهم بهتر، خود پیام‌های مشترک را هم نگه می‌داریم.
  */
  const sharedMessages = sharedBeforeIndexes.map(i => ({
    indexBefore: i,
    indexAfter: sharedAfterIndexes[
      sharedBeforeIndexes.indexOf(i)
    ],
    role: beforeMessages[i].role,
    text: beforeMessages[i].text.slice(0, 80)
  }));

  return {
    sharedCount: sharedBefore.length,

    contiguousBefore,
    contiguousAfter,
    sameOrder,

    continuity:
      sharedBefore.length > 0 &&
      contiguousBefore &&
      contiguousAfter &&
      sameOrder,

    sharedBeforeIndexes,
    sharedAfterIndexes,

    sharedMessages
  };
}

const scroller = findScroller();

if (!scroller) {
  console.error("Scroller پیدا نشد.");
} else {

  console.log("Scroller پیدا شد:", scroller);

  let step = STEP_SIZE;

  let recovery = false;
  let recoverySteps = 0;
  let forwardRemaining = 0;

  let iteration = 0;

  while (true) {

    const beforeScroll = scroller.scrollTop;
    const beforeMessages = getMessages();

    if (beforeScroll <= 0) {
      console.log("Already at top.");
      break;
    }

    /*
      حرکت
    */
    scroller.scrollTop = Math.max(
      0,
      beforeScroll - step
    );

    await sleep(WAIT);

    const afterScroll = scroller.scrollTop;
    const afterMessages = getMessages();

    const actualMove =
      beforeScroll - afterScroll;

    const analysis =
      analyzeContinuity(
        beforeMessages,
        afterMessages
      );

    const beforeFingerprints =
      getFingerprints(beforeMessages);

    const afterFingerprints =
      getFingerprints(afterMessages);

    const overlapSet =
      new Set(afterFingerprints);

    const overlapCount =
      beforeFingerprints.filter(
        x => overlapSet.has(x)
      ).length;

    const overlapRatioBefore =
      beforeFingerprints.length
        ? overlapCount / beforeFingerprints.length
        : 0;

    const overlapRatioAfter =
      afterFingerprints.length
        ? overlapCount / afterFingerprints.length
        : 0;

    const middleIndexBefore =
      Math.floor(beforeMessages.length / 2);

    const middleMessageBefore =
      beforeMessages[middleIndexBefore];

    const middleFingerprint =
      middleMessageBefore
        ? fingerprint(middleMessageBefore)
        : null;

    const middleIndexAfter =
      middleFingerprint
        ? afterFingerprints.indexOf(middleFingerprint)
        : -1;

    const middleFound =
      middleIndexAfter !== -1;

    const mode =
      recovery
        ? "recovery"
        : forwardRemaining > 0
          ? "forward_after_recovery"
          : "main";

    console.log({
      iteration: ++iteration,
      mode,

      beforeScroll,
      afterScroll,
      actualMove,
      step,

      countBefore: beforeMessages.length,
      countAfter: afterMessages.length,

      overlapCount,

      overlapRatioBefore:
        Number(overlapRatioBefore.toFixed(3)),

      overlapRatioAfter:
        Number(overlapRatioAfter.toFixed(3)),

      middleIndexBefore,
      middleIndexAfter,
      middleFound,

      sharedCount:
        analysis.sharedCount,

      contiguousBefore:
        analysis.contiguousBefore,

      contiguousAfter:
        analysis.contiguousAfter,

      sameOrder:
        analysis.sameOrder,

      continuity:
        analysis.continuity
    });

    /*
      اگر پیوستگی شکست،
      جزئیات پیام‌های مشترک را هم چاپ کن.
    */
    if (!analysis.continuity) {

      console.warn(
        "⚠️ CONTINUITY PROBLEM",
        {
          iteration,
          mode,
          sharedCount: analysis.sharedCount,
          contiguousBefore: analysis.contiguousBefore,
          contiguousAfter: analysis.contiguousAfter,
          sameOrder: analysis.sameOrder,
          sharedBeforeIndexes:
            analysis.sharedBeforeIndexes,
          sharedAfterIndexes:
            analysis.sharedAfterIndexes,
          sharedMessages:
            analysis.sharedMessages
        }
      );
    }

    /*
      اگر بعد از Recovery هنوز حرکت‌های اضافه داریم
    */
    if (forwardRemaining > 0) {

      forwardRemaining--;

      console.log({
        recoveryForwardStep: true,
        forwardRemaining
      });

      continue;
    }

    /*
      اگر middle گم شده و هنوز Recovery شروع نشده
    */
    if (!middleFound && !recovery) {

      recovery = true;
      step = -STEP_SIZE;
      recoverySteps = 1;

      console.log("→ recovery");

      continue;
    }

    /*
      اگر در Recovery هستیم و هنوز middle پیدا نشده
    */
    if (!middleFound && recovery) {

      recoverySteps++;

      continue;
    }

    /*
      middle دوباره پیدا شد:
      برگرد به main و N+1 حرکت جلو برو.
    */
    if (middleFound && recovery) {

      const forwardMoves =
        recoverySteps + 1;

      recovery = false;
      step = STEP_SIZE;

      forwardRemaining =
        forwardMoves;

      recoverySteps = 0;

      console.log({
        recoveryFinished: true,
        recoverySteps,
        forwardMoves,
        positionAfterRecovery: afterScroll
      });

      continue;
    }

    /*
      رسیدن به بالای صفحه
    */
    if (afterScroll <= 0) {

      console.log(
        "Reached top."
      );

      break;
    }
  }

  console.log(
    "Finished."
  );
}

این بار چیزی که برای ما واقعاً تعیین‌کننده است continuity: true/false است.

اگر در کل مسیر continuity: true بماند، آن‌وقت یک قدم مهم‌تر از تست قبلی برداشته‌ایم: دیگر فقط نمی‌دانیم «چند پیام مشترک بودند»، بلکه می‌دانیم اشتراک بین دو snapshot یک قطعهٔ پیوسته و هم‌ترتیب بوده است.

اگر حتی یک CONTINUITY PROBLEM دیدی، همان لاگش را کامل بفرست؛ همان یک مورد برایمان از صدها مورد سالم مهم‌تر است. 🏹

آره 😄 این دفعه قبل از شروع، کنسول را تمیز می‌کنیم تا فقط خروجی همین تست را ببینیم.

فقط یک تغییر داریم: اول کد console.clear() اجرا می‌شود؛ منطق تست را دست نمی‌زنیم.

