        forwardMoves;

      recoverySteps = 0;

      console.log({

        recoveryFinished: true,

        forwardMoves,

        positionAfterRecovery:
          afterScroll
      });

      continue;
    }

    /*
      رسیدن به بالای صفحه
    */

    if (afterScroll <= 0) {

      console.log(
        "Reached top."
      );

      break;
    }
  }

  console.log(
    "Finished."
  );
}

این نسخه عمداً هیچ contiguousBefore یا contiguousAfter ندارد. فقط همان چیزی را که الان برایمان مهم است گزارش می‌کند:

overlapCount + overlapRatio + sameOrder + middleFound

و اگر واقعاً ترتیب مشترک‌ها خراب شود، با ⚠️ ORDER PROBLEM جداگانه شکارش می‌کنیم. 🏹

