آره، این خطا کاملاً مشخصه 😄
چون اسکریپت قبلی هنوز در همان Console scope متغیرهای let را نگه داشته و console.clear() فقط خروجی را پاک می‌کند، نه متغیرها را.

پس این بار کل کد را داخل یک بلوک { ... } می‌گذاریم تا scope جدا داشته باشد. این روش ساده‌تر و مطمئن‌تر است.

فقط همین نسخه را اجرا کن:

JavaScript
console.clear();

{
  const STEP_SIZE = 1200;
  const WAIT = 700;

  function sleep(ms) {
    return new Promise(resolve => setTimeout(resolve, ms));
  }

  function findScroller() {
    const all = document.querySelectorAll("div");
    let best = null;
    let bestScore = 0;

    for (const el of all) {
      const style = getComputedStyle(el);

      if (
        (style.overflowY === "auto" || style.overflowY === "scroll") &&
        el.scrollHeight > el.clientHeight + 100
      ) {
        const score = el.scrollHeight - el.clientHeight;

        if (score > bestScore) {
          bestScore = score;
          best = el;
        }
      }
    }

    return best;
  }

  function getMessages() {
    return [...document.querySelectorAll("[data-message-author-role]")]
      .map(el => ({
        role: el.getAttribute("data-message-author-role"),
        text: el.innerText.trim()
      }))
      .filter(m => m.text);
  }

  function fingerprint(message) {
    return message.role + "::" + message.text;
  }

  function getFingerprints(messages) {
    return messages.map(fingerprint);
  }

  function analyzeOrder(beforeMessages, afterMessages) {

    const before = getFingerprints(beforeMessages);
    const after = getFingerprints(afterMessages);

    const afterSet = new Set(after);

    const sharedBefore =
      before.filter(x => afterSet.has(x));

    const beforeSet = new Set(before);

    const sharedAfter =
      after.filter(x => beforeSet.has(x));

    const sameOrder =
      sharedBefore.length === sharedAfter.length &&
      sharedBefore.every(
        (value, index) => value === sharedAfter[index]
      );

    return {
      sharedCount: sharedBefore.length,
      sameOrder,
      sharedBefore,
      sharedAfter
    };
  }

  const scroller = findScroller();

  if (!scroller) {

    console.error("Scroller پیدا نشد.");

  } else {

    console.log("Scroller پیدا شد.");

    let step = STEP_SIZE;

    let recovery = false;
    let recoverySteps = 0;
    let forwardRemaining = 0;

    let iteration = 0;

    while (true) {

      const beforeScroll = scroller.scrollTop;
      const beforeMessages = getMessages();

      if (beforeScroll <= 0) {
        console.log("Already at top.");
        break;
      }

      scroller.scrollTop =
        Math.max(0, beforeScroll - step);

      await sleep(WAIT);

      const afterScroll = scroller.scrollTop;
      const afterMessages = getMessages();

      const actualMove =
        beforeScroll - afterScroll;

      const beforeFP =
        getFingerprints(beforeMessages);

      const afterFP =
        getFingerprints(afterMessages);

      const afterSet =
        new Set(afterFP);

      const overlapCount =
        beforeFP.filter(x => afterSet.has(x)).length;

      const overlapRatioBefore =
        beforeFP.length
          ? overlapCount / beforeFP.length
          : 0;

      const overlapRatioAfter =
        afterFP.length
          ? overlapCount / afterFP.length
          : 0;

      const order =
        analyzeOrder(
          beforeMessages,
          afterMessages
        );

      const middleIndexBefore =
        Math.floor(beforeMessages.length / 2);

      const middleMessageBefore =
        beforeMessages[middleIndexBefore];

      const middleFingerprint =
        middleMessageBefore
          ? fingerprint(middleMessageBefore)
          : null;

      const middleIndexAfter =
        middleFingerprint
          ? afterFP.indexOf(middleFingerprint)
          : -1;

      const middleFound =
        middleIndexAfter !== -1;

      const mode =
        recovery
          ? "recovery"
          : forwardRemaining > 0
            ? "forward_after_recovery"
            : "main";

      console.log({

        iteration: ++iteration,

        mode,

        beforeScroll,
        afterScroll,
        actualMove,
        step,

        countBefore:
          beforeMessages.length,

        countAfter:
          afterMessages.length,

        overlapCount,

        overlapRatioBefore:
          Number(overlapRatioBefore.toFixed(3)),

        overlapRatioAfter:
          Number(overlapRatioAfter.toFixed(3)),

        sharedCount:
          order.sharedCount,

        sameOrder:
          order.sameOrder,

        middleIndexBefore,
        middleIndexAfter,
        middleFound
      });

      if (!order.sameOrder) {

        console.warn(
          "⚠️ ORDER PROBLEM",
          {
            iteration,
            mode,

            sharedCount:
              order.sharedCount,

            sharedBefore:
              order.sharedBefore,

            sharedAfter:
              order.sharedAfter
          }
        );
      }

      if (forwardRemaining > 0) {

        forwardRemaining--;

        console.log({
          recoveryForwardStep: true,
          forwardRemaining
        });

        continue;
      }

      if (!middleFound && !recovery) {

        recovery = true;
        step = -STEP_SIZE;
        recoverySteps = 1;

        console.log("→ recovery");

        continue;
      }

      if (!middleFound && recovery) {

        recoverySteps++;

        continue;
      }

      if (middleFound && recovery) {

        const forwardMoves =
          recoverySteps + 1;

        recovery = false;
        step = STEP_SIZE;

        forwardRemaining =
          forwardMoves;

        recoverySteps = 0;

        console.log({

          recoveryFinished: true,

          forwardMoves,

          positionAfterRecovery:
            afterScroll
        });

        continue;
      }

      if (afterScroll <= 0) {

        console.log(
          "Reached top."
        );

        break;
      }
    }

    console.log(
      "Finished."
    );
  }
}

این بار { ... } باعث می‌شود STEP_SIZE و بقیه متغیرهای let/const با اجرای قبلی تداخل نداشته باشند.

