این نسخه موتور حرکت تأییدشده را نگه می‌دارد و فقط استخراج را به آن اضافه می‌کند. فعلاً هم هیچ سنجش تازه‌ای وارد منطق حرکت نمی‌کنیم.

یک نکتهٔ طراحی: چون از پایین به بالا حرکت می‌کنیم، پیام‌ها را بر اساس شناسهٔ ترتیبیِ مشاهده‌شده در مسیر نگه می‌داریم و در پایان ترتیب را برمی‌گردانیم. برای این تست، خروجی را مستقیم در window.chatExtraction می‌گذاریم تا اول خود داده را ببینیم؛ بعد سراغ JSON و فایل می‌رویم.

JavaScript
{
  const STEP_SIZE = 1200;
  const WAIT = 700;

  const selector = '[data-message-author-role]';

  const sleep = ms => new Promise(r => setTimeout(r, ms));

  const getScroller = () => {
    const candidates = [...document.querySelectorAll('div')];

    return candidates.find(el => {
      const s = getComputedStyle(el);
      return (
        s.overflowY === 'auto' &&
        el.scrollHeight > el.clientHeight &&
        el.clientHeight > 300
      );
    });
  };

  const getMessages = () => {
    return [...document.querySelectorAll(selector)]
      .map((el, index) => ({
        role: el.getAttribute('data-message-author-role'),
        text: el.innerText.trim(),
        index
      }))
      .filter(x => x.text);
  };

