      };

      recoveryLog.push(record);

      console.warn(
        '🔎 RECOVERY TRACE',
        record
      );
    }

    iteration++;

    if (forwardRemaining > 0) {
      forwardRemaining--;
      previousMessages = messages;

      if (after <= 0) {
        break;
      }

      continue;
    }

    if (!middleFound && !recovery) {
      recovery = true;
      step = -STEP_SIZE;
      recoverySteps = 1;

      console.warn(
        '🚨 RECOVERY START',
        {
          iteration,
          before,
          after,
          recoverySteps
        }
      );

      previousMessages = messages;
      continue;
    }

    if (!middleFound && recovery) {
      recoverySteps++;

      previousMessages = messages;
      continue;
    }

    if (middleFound && recovery) {
      const forwardMoves = recoverySteps + 1;

      console.warn(
        '🟢 RECOVERY END',
        {
          iteration,
          recoverySteps,
          forwardMoves
        }
      );

      recovery = false;
      step = STEP_SIZE;
      forwardRemaining = forwardMoves;
      recoverySteps = 0;

      previousMessages = messages;
      continue;
    }

    previousMessages = messages;

    if (after <= 0) {
      break;
    }
  }

  const orderedKeys = [...observationOrder].reverse();

  const extractedMessages = orderedKeys.map(
    key => collected.get(key)
  );

  window.chatExtraction = {
    extractedAt: new Date().toISOString(),
    messageCount: extractedMessages.length,
    messages: extractedMessages
  };

  // ردپای جرم را جداگانه نگه می‌داریم
  window.recoveryTrace = {
    extractedAt: new Date().toISOString(),
    recoveryCount: recoveryLog.length,
    recoveries: recoveryLog
  };

  console.log('');
  console.log('====================================');
  console.log('✅ EXTRACTION FINISHED');
  console.log('====================================');
  console.log(
    'Extracted messages:',
    extractedMessages.length
  );
  console.log(
    'Recovery events:',
    recoveryLog.length
  );
  console.log(
    'Available as:',
    'window.chatExtraction'
  );
  console.log(
    'Recovery trace:',
    'window.recoveryTrace'
  );
  console.log('====================================');

  console.log(extractedMessages);
}
