{
  const STEP_SIZE = 1200;
  const WAIT = 700;

  const selector = '[data-message-author-role]';

  const sleep = ms => new Promise(r => setTimeout(r, ms));

  const getScroller = () => {
    const candidates = [...document.querySelectorAll('div')];

    return candidates.find(el => {
      const s = getComputedStyle(el);

      return (
        s.overflowY === 'auto' &&
        el.scrollHeight > el.clientHeight &&
        el.clientHeight > 300
      );
    });
  };

  const getMessages = () => {
    const elements = [...document.querySelectorAll(selector)];

    return elements
      .map((el, domIndex) => {
        const rect = el.getBoundingClientRect();

        return {
          role: el.getAttribute('data-message-author-role'),
          text: el.innerText.trim(),
          domIndex,
          top: rect.top,
          height: rect.height
        };
      })
      .filter(x => x.text);
  };

  const fingerprint = msg =>
    `${msg.role}|||${msg.text}`;

  const scroller = getScroller();

  if (!scroller) {
    console.error('❌ Chat scroller پیدا نشد.');
    return;
  }

  console.clear();

  let step = STEP_SIZE;

  let recovery = false;
  let recoverySteps = 0;
  let forwardRemaining = 0;

  let previousMessages = getMessages();

  const collected = new Map();
  const observationOrder = [];

  const captureLog = [];

  // ثبت snapshot اولیه
  for (const msg of previousMessages) {
    const key = fingerprint(msg);

    if (!collected.has(key)) {
      collected.set(key, {
        role: msg.role,
        text: msg.text,
        firstSeenAt: observationOrder.length
      });

      observationOrder.push(key);
    }
  }

  let iteration = 0;

  while (true) {
    const before = scroller.scrollTop;

    const movementDirection =
      step > 0
        ? 'main_toward_top'
        : 'recovery_toward_bottom';

    scroller.scrollTop = Math.max(
      0,
      before - step
    );

    await sleep(WAIT);

    const after = scroller.scrollTop;

    const messages = getMessages();

    /*
      ترتیب فضایی همین snapshot
    */
    const spatialMessages = [...messages]
      .sort((a, b) => a.top - b.top);

    /*
      بررسی اینکه DOM و موقعیت فضایی یکسان‌اند یا نه
    */
    const domMatchesSpatial =
      messages.length === spatialMessages.length &&
      messages.every((msg, i) =>
        fingerprint(msg) ===
        fingerprint(spatialMessages[i])
      );

    /*
      پیام‌های جدید
    */
    const newlyCollected = [];

    for (const msg of messages) {
      const key = fingerprint(msg);

      if (!collected.has(key)) {
        const record = {
          role: msg.role,
          text: msg.text,
          domIndex: msg.domIndex,
          top: msg.top,
          firstSeenAt: observationOrder.length,
          movementDirection
        };

        collected.set(key, {
          role: msg.role,
          text: msg.text,
          firstSeenAt: observationOrder.length
        });

        observationOrder.push(key);

        newlyCollected.push(record);
      }
    }

    /*
      middle قبلی
    */
    const middle =
      previousMessages.length > 0
        ? previousMessages[
            Math.floor(previousMessages.length / 2)
          ]
        : null;

    let middleFound = false;

    if (middle) {
      const middleKey = fingerprint(middle);

      middleFound = messages.some(
        msg => fingerprint(msg) === middleKey
      );
    }

    const mode =
      recovery
        ? 'recovery'
        : forwardRemaining > 0
          ? 'forward_after_recovery'
          : 'main';

    /*
      ثبت گزارش فقط وقتی اتفاق مهمی رخ داده
    */
    if (
      newlyCollected.length > 0 ||
      !middleFound ||
      recovery ||
      forwardRemaining > 0
    ) {
      const record = {
        iteration,
        before,
        after,
        mode,
        movementDirection,
        visibleMessages: messages.length,
        collectedMessages: collected.size,
        newlyCollected,
        domMatchesSpatial,
        domOrder: messages.map(msg => ({
          role: msg.role,
          text: msg.text.slice(0, 120),
          domIndex: msg.domIndex,
          top: msg.top
        })),
        spatialOrder: spatialMessages.map(msg => ({
          role: msg.role,
          text: msg.text.slice(0, 120),
          domIndex: msg.domIndex,
          top: msg.top
        })),
        middleFound
      };

      captureLog.push(record);

      console.log(
        '📸 SNAPSHOT',
        record
      );
    }

    iteration++;

    /*
      ادامهٔ forward-after-recovery
    */
    if (forwardRemaining > 0) {
      forwardRemaining--;

      previousMessages = messages;

      if (after <= 0) {
        break;
      }

      continue;
    }

    /*
      ورود به recovery
    */
    if (!middleFound && !recovery) {
      recovery = true;
      step = -STEP_SIZE;
      recoverySteps = 1;

      console.warn(
        '🚨 RECOVERY START',
        {
          iteration,
          before,
          after,
          recoverySteps
        }
      );

      previousMessages = messages;
      continue;
    }

    /*
      ادامهٔ recovery
    */
    if (!middleFound && recovery) {
      recoverySteps++;

      previousMessages = messages;
      continue;
    }

    /*
      پایان recovery
    */
    if (middleFound && recovery) {
      const forwardMoves = recoverySteps + 1;

      console.warn(
        '🟢 RECOVERY END',
        {
          iteration,
          recoverySteps,
          forwardMoves
        }
      );

      recovery = false;
      step = STEP_SIZE;
      forwardRemaining = forwardMoves;
      recoverySteps = 0;

      previousMessages = messages;
      continue;
    }

    previousMessages = messages;

    if (after <= 0) {
      break;
    }
  }

  /*
    خروجی نهایی
  */
  const orderedKeys =
    [...observationOrder].reverse();

  const extractedMessages =
    orderedKeys.map(
      key => collected.get(key)
    );

  window.chatExtraction = {
    extractedAt: new Date().toISOString(),
    messageCount: extractedMessages.length,
    messages: extractedMessages
  };

  /*
    گزارش تشخیصی
  */
  window.extractionDiagnostic = {
    extractedAt: new Date().toISOString(),
    messageCount: extractedMessages.length,
    captureCount: captureLog.length,
    captures: captureLog
  };

  console.log('');
  console.log('====================================');
  console.log('🔬 DIAGNOSTIC EXTRACTION FINISHED');
  console.log('====================================');
  console.log(
    'Extracted messages:',
    extractedMessages.length
  );
  console.log(
    'Diagnostic snapshots:',
    captureLog.length
  );
  console.log(
    'Extraction:',
    'window.chatExtraction'
  );
  console.log(
    'Diagnostic:',
    'window.extractionDiagnostic'
  );
  console.log('====================================');
}
