🏹 پس این بار یک تست، یک خروجی، بدون مرحلهٔ اضافی.

کد زیر را اجرا کن؛ همان منطق قبلی را نگه می‌دارد و فقط برای هر پیام تازه، ترتیب DOM و ترتیب ورود به صف را در یک لاگ ثبت می‌کند. بعد از پایان فقط window.queueDiagnostic را بررسی می‌کنیم.

JavaScript
{
  const STEP_SIZE = 1200;
  const WAIT = 700;
  const selector = '[data-message-author-role]';

  const sleep = ms => new Promise(r => setTimeout(r, ms));

  const getScroller = () =>
    [...document.querySelectorAll('div')].find(el => {
      const s = getComputedStyle(el);
      return (
        s.overflowY === 'auto' &&
        el.scrollHeight > el.clientHeight &&
        el.clientHeight > 300
      );
    });

  const getMessages = () =>
    [...document.querySelectorAll(selector)]
      .map((el, domIndex) => ({
        role: el.getAttribute('data-message-author-role'),
        text: el.innerText.trim(),
        domIndex
      }))
      .filter(x => x.text);

  const fingerprint = msg =>
    `${msg.role}|||${msg.text}`;

  const scroller = getScroller();

  if (!scroller) {
    console.error('❌ Chat scroller پیدا نشد.');
    return;
  }

  console.clear();

  let step = STEP_SIZE;
  let recovery = false;
  let recoverySteps = 0;
  let forwardRemaining = 0;

  let previousMessages = getMessages();

  const collected = new Map();
  const observationOrder = [];
  const queueDiagnostic = [];

  for (const msg of previousMessages) {
    const key = fingerprint(msg);

    if (!collected.has(key)) {
      collected.set(key, {
        role: msg.role,
        text: msg.text
      });
      observationOrder.push(key);
    }
  }

  let iteration = 0;

  while (true) {
    const before = scroller.scrollTop;

    scroller.scrollTop = Math.max(
      0,
      before - step
    );

    await sleep(WAIT);

    const after = scroller.scrollTop;
    const messages = getMessages();

    const newMessages = [];

    for (const msg of messages) {
      const key = fingerprint(msg);

      if (!collected.has(key)) {
        newMessages.push({
          domIndex: msg.domIndex,
          role: msg.role,
          text: msg.text.slice(0, 120)
        });

        collected.set(key, {
          role: msg.role,
          text: msg.text
        });

        observationOrder.push(key);
      }
    }

    if (newMessages.length > 0) {
      queueDiagnostic.push({
        iteration,
        mode:
          recovery
            ? 'recovery'
            : forwardRemaining > 0
              ? 'forward_after_recovery'
              : 'main',
        before,
        after,

        // ترتیب کل snapshot در DOM
        domOrder: messages.map(msg => ({
          domIndex: msg.domIndex,
          role: msg.role,
          text: msg.text.slice(0, 120)
        })),

        // دقیقاً همان ترتیبی که وارد صف شدند
        newMessages
      });
    }

    const middle =
      previousMessages.length > 0
        ? previousMessages[
            Math.floor(previousMessages.length / 2)
          ]
        : null;

    const middleFound =
      middle &&
      messages.some(
        msg =>
          fingerprint(msg) === fingerprint(middle)
      );

    iteration++;

    if (forwardRemaining > 0) {
      forwardRemaining--;
      previousMessages = messages;

      if (after <= 0) break;
      continue;
    }

    if (!middleFound && !recovery) {
      recovery = true;
      step = -STEP_SIZE;
      recoverySteps = 1;
      previousMessages = messages;
      continue;
    }

    if (!middleFound && recovery) {
      recoverySteps++;
      previousMessages = messages;
      continue;
    }

    if (middleFound && recovery) {
      const forwardMoves = recoverySteps + 1;

      recovery = false;
      step = STEP_SIZE;
      forwardRemaining = forwardMoves;
      recoverySteps = 0;
      previousMessages = messages;
      continue;
    }

    previousMessages = messages;

    if (after <= 0) break;
  }

  window.queueDiagnostic = queueDiagnostic;

  console.log(
    '✅ تمام شد — snapshotهای دارای پیام جدید:',
    queueDiagnostic.length
  );
  console.log(
    '📦 window.queueDiagnostic'
  );
}

